/usr/bin/bash -lc "cat > index.html <<'EOF'
<"'!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#344e75"><title>Tern Works — Inventory</title><link rel="stylesheet" href="tokens.css"><link rel="stylesheet" href="styles.css"></head>
<body>
<a class="skip" href="#inventory">Skip to inventory</a>
<header class="topbar"><a class="brand" href="index.html" aria-label="Tern Works inventory home"><span class="brand-mark" aria-hidden="true">T<span>↗</span></span> TERN WORKS</a><span class="workspace">Operations workspace</span><span class="role"><span aria-hidden="true">●</span> Inventory editor</span></header>
<main id="app">
<div class="page-heading"><div><p class="eyebrow">OPERATIONS / INVENTORY</p><h1>Every part, in place.</h1><p class="intro">Your product catalogue, stock levels and supply details.</p></div><span class="session-note">Session workspace <span>Changes stay in this tab</span></span></div>
<section class="summary" aria-label="Inventory overview" id="summary"></section>
<section class="inventory" id="inventory" aria-labelledby="inventory-title" tabindex="-1">
<div class="section-heading"><div><h2 id="inventory-title">Product inventory</h2><p>Consult every record. Update the products you manage.</p></div><span class="catalogue-label">TERN / CATALOGUE</span></div>
<div class="filters"><label class="search-label"><span>Search products</span><div class="search-box"><span aria-hidden="true">⌕</span><input type="search" data-testid="search" id="search" placeholder="Search by name or SKU" autocomplete="off"></div></label><label>Category<select id="category"><option value="">All categories</option></select></label><label>Lifecycle status<select id="status"><option value="">All statuses</option></select></label><label>Stock level<select id="stock"><option value="">All stock levels</option><option value="out">Out of stock · 0</option><option value="low">Low stock · 1–10</option><option value="healthy">In stock · 11+</option></select></label></div>
<div id="active-filters" class="active-filters" aria-label="Active filters"></div>
<div class="results-bar"><p id="result-count" role="status" aria-live="polite"></p><span class="currency-note">Prices in USD · per unit</span></div>
<div id="results"></div>
<div class="inventory-footer"><span>Fictional inventory · Tern Works</span><span>Restricted records are managed by procurement.</span></div>
</section>
<footer class="page-footer"><span>TERN WORKS</span><span>Built for the work ahead.</span></footer>
</main>
<div class="toast" id="notice" role="status" aria-live="polite" hidden></div>
<dialog id="record-dialog" aria-labelledby="dialog-title"><div id="dialog-content"></div></dialog>
<script type="module" src="app.js"></script>
</body></html>
EOF
