.7;padding:14px;background:#edf1f6;border-radius:6px;margin:24px 0 0}.permission strong{display:block;color:var(--ink)}.dialog-actions{padding:18px 26px;display:flex;justify-content:flex-end;gap:10px;border-top:1px solid var(--line);background:#fafbfd}.editor{display:flex;flex-direction:column;gap:20px}.editor textarea{font:inherit;resize:vertical;min-height:90px;max-height:240px;width:100%;padding:10px;border:1px solid #b9c4d1;border-radius:5px;font-size:14px;color:var(--ink)}textarea:focus-visible{outline:3px solid var(--accent);outline-offset:3px}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:18px}.hint{font-size:11px;font-weight:400;color:var(--muted)}.field-error{color:var(--danger);font-size:12px;font-weight:500;line-height:1.5}.field-error:empty{display:none}[aria-invalid=true]{border-color:var(--danger)"'!important}.discard{background:#fff4e9;border:1px solid #e4bd96;border-radius:6px;padding:16px;margin:0 26px 20px;font-size:13px;line-height:1.5}.discard p{margin:0 0 12px}.discard div{display:flex;gap:10px;flex-wrap:wrap}.discard[hidden]{display:none}.scroll-hint{display:none}
